use std::sync::OnceLock;

/// Decode the embedded blob once: `templates()[d]` holds the canonical masks
/// of digit d+1.
pub fn templates() -> &'static [Vec<Vec<u8>>] {
    static TPL: OnceLock<Vec<Vec<Vec<u8>>>> = OnceLock::new();
    TPL.get_or_init(|| {
        let b64: String = OCR_TEMPLATES.chars().filter(|c| !c.is_whitespace()).collect();
        let raw = crate::ocr::zlib_decompress(&b64_decode(&b64).expect("template blob decodes"))
            .expect("template blob inflates");
        let mut out: Vec<Vec<Vec<u8>>> = Vec::new();
        let mut pos = 0usize;
        for _ in 0..9 {
            let count = u16::from_le_bytes([raw[pos], raw[pos + 1]]) as usize;
            pos += 2;
            let mut masks = Vec::with_capacity(count);
            for _ in 0..count {
                masks.push(raw[pos..pos + 384].to_vec());
                pos += 384;
            }
            out.push(masks);
        }
        assert_eq!(pos, raw.len(), "template blob fully consumed");
        out
    })
}

/// Standard base64 (with padding); used only for the embedded blob.
fn b64_decode(s: &str) -> Option<Vec<u8>> {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut rev = [255u8; 256];
    for (i, &c) in T.iter().enumerate() {
        rev[c as usize] = i as u8;
    }
    let bytes: Vec<u8> = s.bytes().filter(|&c| c != b'=').collect();
    if (s.len() - bytes.len()) > 2 || bytes.len() % 4 == 1 {
        return None;
    }
    let mut out = Vec::with_capacity(bytes.len() * 3 / 4);
    for chunk in bytes.chunks(4) {
        let mut acc = 0u32;
        for (i, &c) in chunk.iter().enumerate() {
            let v = rev[c as usize];
            if v == 255 {
                return None;
            }
            acc |= (v as u32) << (18 - 6 * i);
        }
        out.push((acc >> 16) as u8);
        if chunk.len() > 2 {
            out.push((acc >> 8) as u8);
        }
        if chunk.len() > 3 {
            out.push(acc as u8);
        }
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn blob_decodes_to_nine_digit_template_sets() {
        let tpl = templates();
        assert_eq!(tpl.len(), 9);
        for (d, set) in tpl.iter().enumerate() {
            assert!(!set.is_empty(), "digit {} has templates", d + 1);
            for m in set {
                assert_eq!(m.len(), 16 * 24);
            }
        }
        // base64 helper agrees with the reference encoding
        assert_eq!(b64_decode("QQ==").unwrap(), b"A");
        assert_eq!(b64_decode("QUI=").unwrap(), b"AB");
        assert_eq!(b64_decode("QUJD").unwrap(), b"ABC");
    }
}
